### 주식
- 하루에 주식을 하나를 사거나, 가지고 있는 주식을 팔거나 아무것도 안 할 수 있는데, 최대 이익을 내야한다.
- 계속 주식을 사다가 최대 값일때 팔고 그 이후 나머지 주가 중 최대 값일 때 또 팔면 된다.
  - 이를 Rank 를 사용하여 rank를 정렬한 후, 
  - 랭크1의 index까지 계속 사다가 팔고, 
  - 이후 랭크를 1더하고 이를 반복하는 방식으로 해결
```
public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int t = Integer.parseInt(br.readLine());

		for (int i = 0; i < t; i++) {

			int N = Integer.parseInt(br.readLine());
			Integer[] nList = Arrays.stream(br.readLine().split(" "))
				.map(data -> Integer.parseInt(data))
				.toArray(Integer[]::new);
			new Stock().solution(N, nList);
		}
	}

	private void solution(int n, Integer[] nList) {
		Rank[] ranks = new Rank[n]; // rank생성
		for (int i = 0; i < n; i++) {
			ranks[i] = new Rank(i, nList[i]);
		}
               // 랭킹 초기화
		Rank[] sortedRanks = Arrays.stream(ranks)
			.sorted((rank1, rank2) -> {
				return rank2.data.compareTo(rank1.data);
			})
			.toArray(Rank[]::new);

		long sum = 0;
		int rankIndex = 0;
		long cost = 0;
		long count = 0;
		for (int i = 0; i < n; i++) {
                       // 현재 index와, 랭킹의 index를 비교하여
			if (i == sortedRanks[rankIndex].index) { //   같으면 판매
				sum += nList[i] * count - cost; // 현재 주가 * 갯수 - 지금까지 구매한 cost

                               // 랭킹 업데이트
				while (rankIndex < n && i >= sortedRanks[rankIndex].index) {  // 랭킹의 index가 현재  index보다 작거나 rankIndex가 전체 사이즈보다 작을 경우에만 ++
					rankIndex++;
				}

				cost = 0;
				count = 0;
			} else { // 다르면 구매
				count++;
				cost += nList[i]; // 구매한 cost 증가
			}
		}

		sum += nList[n-1] * count - cost; // 마지막 남은 cost까지 추가
		System.out.println(sum);
	}

	class Rank {
		int index;
		Integer data;

		public Rank(int index, int data) {
			this.index = index;
			this.data = data;
		}
	}
```

### 잃어버린 괄호
- 최소를 만들고 +, -, 괄호만 있기 때문에 -가 나오는 순간부터 모든 데이터는 빼는 것으로 하면 된다.
```
public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		String expression = br.readLine();

		new LostBrackets().solution(expression);
	}

	private void solution(String expression) {
		StringBuilder sb = new StringBuilder();

		boolean minusStart = false;
		int result = 0;
		for (int i = 0; i < expression.length(); i++) {
			if (expression.charAt(i) >= '0' && expression.charAt(i) <= '9') { // 숫자 만들고
				sb.append(expression.charAt(i));
				continue;
			}

			if (!sb.isEmpty()) { // 숫자가 만들어 졌으면
				result = calc(result, sb.toString(), minusStart); // 방정식 계산
				sb = new StringBuilder();
			}

			if (expression.charAt(i) == '-') { // minus가 나오면 그 순간부터는 뺄셈
				minusStart = true;
			}
		}

		if (sb.length() != 0) {
			result = calc(result, sb.toString(), minusStart);
		}

		System.out.println(result);
	}

	private int calc(int result, String data, boolean minusStart) {
		if (minusStart) {
			return  result - Integer.parseInt(data.toString());
		}

		return result + Integer.parseInt(data.toString());
	}
