### 계란으로 계란치기
- 계란으로 계란을 부수는 과정에서 최대 값을 구해야 한다.
- 모든 경우의 수를 확인해야 하며, 정렬할 수 없으므로 그리디는 제외, 변화에 대한 현재 상태 알아야하고, 이전으로 돌아갈 수 있어야한다.
- 따라서 dfs로 모든 경우 탐색
```
public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int n = Integer.parseInt(br.readLine());

		Egg[] eggs = new Egg[n];
		for (int i = 0; i < n; i++) {
			String[] input = br.readLine().split(" ");
			eggs[i] = new Egg(Integer.parseInt(input[0]), Integer.parseInt(input[1]));
		}

		new EggToEgg().solution(eggs);
	}

	private void solution(Egg[] eggs) {
		System.out.println(dfs(eggs, 0));
	}

	private int dfs(Egg[] eggs, int eggIndex) {
		if (eggIndex == eggs.length ) {
			return calc(eggs); // 깨져있는 계란의 갯수
		}

		int result = 0;
		for (int i = 0; i < eggs.length; i++) {
			if (eggs[eggIndex].durability <= 0) { // 손에 들고있는 계란이 깨지면
				int temp = dfs(eggs, eggIndex+1); // 다음 계란 탐색
				result = result < temp ? temp : result;
				continue;
			}

			if (eggIndex == i || eggs[i].durability <= 0) { // 현재 손에 들고있는 계란 or 계란이 깨져있거나
				continue;
			}

                       // 나머지는 계란 부수는 과정 작업 후 되돌리기
			eggs[eggIndex].durability -= eggs[i].weight;
			eggs[i].durability -= eggs[eggIndex].weight;
			int temp = dfs(eggs, eggIndex+1);
			result = result < temp ? temp : result;
			eggs[eggIndex].durability += eggs[i].weight;
			eggs[i].durability += eggs[eggIndex].weight;
		}

		int total = calc(eggs);

		return result < total ? total : result;
	}

        // egg들 중 깨져있는 계란의 갯수
	private int calc(Egg[] eggs) {
		int total = 0;
		for (int i = 0; i < eggs.length; i++) {
			if (eggs[i].durability <= 0) {
				total++;
			}
		}

		return total;
	}

	static class Egg {
		int durability;
		int weight;

		public Egg(int durability, int weight) {
			this.durability = durability;
			this.weight = weight;
		}
	}
